WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) AS prev_event_time FROM web_events), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT s.id, s.session_id, s.event_type, s.new_group_flag, s.session_no, (SELECT MAX(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS max_web_event_duration_sec FROM sessions_web_events s ORDER BY event_type;
